const r=await tools.exec_command({cmd:"cat > /Users/yihdu/.codex/codefield_gateway_adapter.py <<'PY'
"""Local Responses proxy for Codefield's mixed-tool compatibility issue.

Codex sends web_search alongside function tools. The upstream gateway rejects
that combination for Gemini Flash. This proxy omits web_search for this
provider and keeps Codex's local function tools available.
"""

from http.client import HTTPSConnection
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import json
import os

UPSTREAM = "llm-api.cc"
PORT = 18788


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, *_args):
        pass

    def do_GET(self):
        self.forward()

    def do_POST(self):
        self.forward()

    def forward(self):
        if not self.path.startswith("/api/v1/"):
            self.send_error(404)
            return
        body = self.rfile.read(int(self.headers.get("Content-Length", "0")))
        if self.path.split("?", 1)[0] == "/api/v1/responses" and body:
            try:
                request = json.loads(body)
                request["tools"] = [
                    tool for tool in request.get("tools", [])
                    if tool.get("type") in ("function", "namespace")
                ]
                request.setdefault("tool_config", {})[
                    "include_server_side_tool_invocations"
                ] = True
                body = json.dumps(request, separators=(",", ":")).encode()
            except (ValueError, TypeError, AttributeError):
                self.send_error(400)
                return
        headers = {
            key: value for key, value in self.headers.items()
            if key.lower() not in {"host", "connection", "content-length", "accept-encoding"}
        }
        headers.update({
            "Host": UPSTREAM,
            "Content-Length": str(len(body)),
            "Accept-Encoding": "identity",
            "User-Agent": "curl/8.7.1",
        })
        connection = HTTPSConnection(UPSTREAM, timeout=120)
        try:
            connection.request(self.command, self.path, body=body or None, headers=headers)
            response = connection.getresponse()
            self.send_response(response.status)
            for key, value in response.getheaders():
                if key.lower() not in {"connection", "transfer-encoding", "content-length", "content-encoding"}:
                    self.send_header(key, value)
            self.send_header("Connection", "close")
            self.end_headers()
            while chunk := response.read1(4096):
                self.wfile.write(chunk)
                self.wfile.flush()
        except (OSError, BrokenPipeError):
            if not self.wfile.closed:
                try:
                    self.send_error(502)
                except OSError:
                    pass
        finally:
            self.close_connection = True
            connection.close()


if __name__ == "__main__":
    ThreadingHTTPServer(("127.0.0.1", PORT), Handler).serve_forever()
PY","max_output_tokens":100}); text(r.output)

